#!/usr/bin/env node
/**
 * Bundles userscript/main.ts (+ the capture logic of @m365copilot/core it
 * shares with the browser extension) into m365copilot-token.user.js, the
 * file users install in Tampermonkey/Violentmonkey.
 *
 *   node scripts/build-userscript.mjs                 write the .user.js
 *   node scripts/build-userscript.mjs --check         exit 1 if it is out of date
 *   node scripts/build-userscript.mjs --release <dir> write a copy into <dir>
 *     (`pnpm package` → releases/tampermonkey, published by the release workflow)
 *
 * The generated file is committed (it is installed straight from GitHub and
 * auto-updates through @updateURL), so `pnpm build` regenerates it and the
 * tests run the --check: the userscript can no longer fall behind the
 * extension the way the hand-written one did.
 */
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "tsdown";

const ROOT = fileURLToPath(new URL("..", import.meta.url));
const OUTPUT = join(ROOT, "m365copilot-token.user.js");
const REPO = "https://github.com/cristiancastineiras/M365CopilotVSCode";
const RAW =
  "https://raw.githubusercontent.com/cristiancastineiras/M365CopilotVSCode/main/extensiones/vscode/m365copilot-token.user.js";
const MATCHES = [
  "https://m365.cloud.microsoft/*",
  "https://*.cloud.microsoft/*",
  "https://www.office.com/*",
  "https://outlook.office.com/*",
  "https://teams.microsoft.com/*",
];
const GRANTS = [
  "GM_getValue",
  "GM_setValue",
  "GM_addValueChangeListener",
  "GM_setClipboard",
  "GM_xmlhttpRequest",
  "GM_registerMenuCommand",
  "unsafeWindow",
];

function metadata(version) {
  const lines = [
    ["name", "M365 Copilot — token → VS Code"],
    ["name:es", "M365 Copilot — token → VS Code"],
    ["namespace", REPO],
    ["version", version],
    [
      "description",
      "Captures your Microsoft 365 Copilot session token and sends it to the M365 Copilot extension for VS Code automatically (or lets you copy it).",
    ],
    [
      "description:es",
      "Captura el token de tu sesión de Microsoft 365 Copilot y lo envía a la extensión M365 Copilot de VS Code automáticamente (o te deja copiarlo).",
    ],
    ["author", "Cristian Castineiras"],
    ["homepageURL", REPO],
    ["supportURL", `${REPO}/issues`],
    ["updateURL", RAW],
    ["downloadURL", RAW],
    ["run-at", "document-start"],
    ...MATCHES.map((match) => ["match", match]),
    ...GRANTS.map((grant) => ["grant", grant]),
    // The VS Code extension's local server (TOKEN_SERVER_URL in @m365copilot/core).
    ["connect", "localhost"],
  ];
  const width = Math.max(...lines.map(([key]) => key.length)) + 2;
  return [
    "// ==UserScript==",
    ...lines.map(([key, value]) => `// @${key.padEnd(width - 1)}${value}`),
    "// ==/UserScript==",
    "",
    "// GENERATED by extensiones/vscode/scripts/build-userscript.mjs from userscript/main.ts",
    "// and @m365copilot/core — do not edit by hand: run `pnpm build` in extensiones/vscode.",
    "",
  ].join("\n");
}

export async function buildUserscript() {
  const { version } = JSON.parse(readFileSync(join(ROOT, "package.json"), "utf8"));
  const outDir = mkdtempSync(join(tmpdir(), "m365-userscript-"));
  try {
    await build({
      config: false,
      cwd: ROOT,
      entry: { userscript: join(ROOT, "userscript", "main.ts") },
      format: "iife",
      platform: "browser",
      target: "es2020",
      outDir,
      dts: false,
      sourcemap: false,
      minify: false,
      clean: false,
      hash: false,
      logLevel: "warn",
      tsconfig: join(ROOT, "userscript", "tsconfig.json"),
      deps: {
        alwaysBundle: ["@m365copilot/core"],
        neverBundle: true,
      },
      banner: metadata(version),
    });
    const [file] = (await import("node:fs"))
      .readdirSync(outDir)
      .filter((name) => name.endsWith(".js"));
    const output = readFileSync(join(outDir, file), "utf8").replace(/\r\n/g, "\n");
    if (/\b_m365copilot_core\b/.test(output)) {
      throw new Error(
        "The userscript has an unresolved @m365copilot/core global; build the core package before generating it.",
      );
    }
    return output;
  } finally {
    rmSync(outDir, { recursive: true, force: true });
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const fresh = await buildUserscript();
  const releaseAt = process.argv.indexOf("--release");
  if (releaseAt !== -1) {
    const dir = process.argv[releaseAt + 1];
    if (!dir) {
      console.error("Usage: node scripts/build-userscript.mjs --release <dir>");
      process.exit(1);
    }
    mkdirSync(dir, { recursive: true });
    writeFileSync(join(dir, "m365copilot-token.user.js"), fresh);
    console.log(`m365copilot-token.user.js written to ${dir}.`);
  } else if (process.argv.includes("--check")) {
    let current = "";
    try {
      current = readFileSync(OUTPUT, "utf8").replace(/\r\n/g, "\n");
    } catch {
      /* missing counts as stale */
    }
    if (current !== fresh) {
      console.error(
        "m365copilot-token.user.js is out of date: run `pnpm build` in extensiones/vscode.",
      );
      process.exit(1);
    }
    console.log("m365copilot-token.user.js is up to date.");
  } else {
    writeFileSync(OUTPUT, fresh);
    console.log(`m365copilot-token.user.js written (${Math.round(fresh.length / 1024)} KB).`);
  }
}
